test('issueInvoice uses next number based on existing', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const existingNumbers = ['INV-2026-0001', 'INV-2026-0005'];
